-- Quyền cơ cấu tổ chức có backend hỗ trợ: xem, phân công nhân sự, bổ nhiệm quản lý, xem lịch sử.
-- org.manage_structure / org.manage_permissions vẫn là bản nháp cho tới khi backend hỗ trợ.
CREATE OR REPLACE FUNCTION private.base_supported(p text) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$ SELECT p=ANY(ARRAY['sale_work.access','sale_work.view_own','sale_work.manage_settings','sale_work.manage_credentials','sale_work.view_audit','biz.crm_use','org.view','org.assign_staff','org.appoint_manager','org.view_history']) $$;

-- Đơn vị + toàn bộ đơn vị con cháu (theo cây units trong cấu hình).
CREATE OR REPLACE FUNCTION private.base_org_units_below(c jsonb, unit text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH RECURSIVE tree AS (SELECT x->>'id' id FROM jsonb_array_elements(c->'units') x WHERE x->>'id'=unit UNION ALL SELECT x->>'id' FROM jsonb_array_elements(c->'units') x JOIN tree t ON x->>'parent_id'=t.id) SELECT coalesce(jsonb_agg(id),'[]'::jsonb) FROM tree $$;

-- Người dùng có quyền p trên MỌI đơn vị đích không? DENY phủ bất kỳ đơn vị nào sẽ chặn (DENY ưu tiên);
-- quyền không gắn unit_id = toàn Base; quyền gắn unit_id phủ đơn vị đó và con cháu.
CREATE OR REPLACE FUNCTION private.base_org_scope_ok(u uuid, p text, units jsonb) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE rules jsonb;c jsonb;target text;BEGIN c:=private.base_config();rules:=private.base_rules(u,c);IF EXISTS(SELECT 1 FROM jsonb_array_elements(rules) r WHERE r->>'permission'=p AND r->>'effect'='DENY' AND (r->>'unit_id' IS NULL OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(units) t WHERE private.base_org_units_below(c,r->>'unit_id') ? t))) THEN RETURN false;END IF;FOR target IN SELECT jsonb_array_elements_text(units) LOOP IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(rules) r WHERE r->>'permission'=p AND r->>'effect'='ALLOW' AND (r->>'unit_id' IS NULL OR private.base_org_units_below(c,r->>'unit_id') ? target)) THEN RETURN false;END IF;END LOOP;RETURN true;END $$;

-- Áp dụng thay đổi PHÂN CÔNG (chỉ mục memberships) một cách nguyên tử, có kiểm tra phạm vi từng đơn vị.
-- Super Admin toàn quyền; người khác cần org.assign_staff phủ mọi đơn vị bị ảnh hưởng,
-- thay đổi vị trí quản lý đơn nhiệm cần thêm org.appoint_manager; cấm tự bổ nhiệm mình vào vị trí quản lý.
CREATE OR REPLACE FUNCTION public.base_org_membership_apply(_revision bigint,_memberships jsonb,_reason text) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v bigint;c jsonb;newc jsonb;affected jsonb;manager_affected jsonb;is_super boolean;BEGIN IF auth.uid() IS NULL OR NOT private.is_active(auth.uid()) THEN RAISE EXCEPTION 'Vui lòng đăng nhập lại.';END IF;IF jsonb_typeof(_memberships) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Dữ liệu phân công không hợp lệ.';END IF;is_super:=private.is_super_admin(auth.uid());PERFORM pg_advisory_xact_lock(hashtext('base_org'));v:=coalesce((SELECT revision FROM base_org_state WHERE id),0);IF v<>_revision THEN RAISE EXCEPTION 'Dữ liệu đã thay đổi; vui lòng tải lại và xem trước lại.';END IF;c:=private.base_config();IF EXISTS(SELECT 1 FROM jsonb_array_elements(_memberships) m WHERE jsonb_typeof(m)<>'object' OR coalesce(m->>'id','')='' OR coalesce(m->>'user_id','')='' OR coalesce(m->>'unit_id','')='') THEN RAISE EXCEPTION 'Phân công thiếu thông tin bắt buộc.';END IF;IF EXISTS(SELECT 1 FROM jsonb_array_elements(_memberships) m WHERE NOT EXISTS(SELECT 1 FROM profiles p WHERE p.id::text=m->>'user_id')) THEN RAISE EXCEPTION 'Phân công chứa nhân sự không tồn tại.';END IF;IF EXISTS(SELECT 1 FROM jsonb_array_elements(_memberships) m WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(c->'units') x WHERE x->>'id'=m->>'unit_id')) THEN RAISE EXCEPTION 'Phân công chứa đơn vị không tồn tại.';END IF;IF EXISTS(SELECT 1 FROM jsonb_array_elements(_memberships) m WHERE m->>'title_id' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(c->'titles') t WHERE t->>'id'=m->>'title_id')) THEN RAISE EXCEPTION 'Phân công chứa chức danh không tồn tại.';END IF;IF EXISTS(SELECT 1 FROM jsonb_array_elements(_memberships) m WHERE coalesce((m->>'active')::boolean,false) GROUP BY m->>'user_id',m->>'unit_id',coalesce(m->>'title_id','') HAVING count(*)>1) THEN RAISE EXCEPTION 'Trùng phân công đang hiệu lực cho cùng nhân sự, đơn vị và chức danh.';END IF;IF EXISTS(SELECT 1 FROM jsonb_array_elements(_memberships) m JOIN jsonb_array_elements(c->'titles') t ON t->>'id'=m->>'title_id' WHERE coalesce((m->>'active')::boolean,false) AND (coalesce(t->>'kind','')='manager' OR coalesce((t->>'capacity')::int,0)=1) GROUP BY m->>'unit_id',m->>'title_id' HAVING count(*)>1) THEN RAISE EXCEPTION 'Vị trí quản lý đơn nhiệm không thể có hai người cùng hiệu lực.';END IF;SELECT coalesce(jsonb_agg(DISTINCT u),'[]'::jsonb) INTO affected FROM (SELECT m->>'unit_id' u FROM jsonb_array_elements(_memberships) m WHERE NOT (c->'memberships') @> jsonb_build_array(m) UNION SELECT m->>'unit_id' FROM jsonb_array_elements(c->'memberships') m WHERE NOT _memberships @> jsonb_build_array(m)) d;SELECT coalesce(jsonb_agg(DISTINCT u),'[]'::jsonb) INTO manager_affected FROM (SELECT m->>'unit_id' u FROM jsonb_array_elements(_memberships) m JOIN jsonb_array_elements(c->'titles') t ON t->>'id'=m->>'title_id' WHERE NOT (c->'memberships') @> jsonb_build_array(m) AND (coalesce(t->>'kind','')='manager' OR coalesce((t->>'capacity')::int,0)=1) UNION SELECT m->>'unit_id' FROM jsonb_array_elements(c->'memberships') m JOIN jsonb_array_elements(c->'titles') t ON t->>'id'=m->>'title_id' WHERE NOT _memberships @> jsonb_build_array(m) AND (coalesce(t->>'kind','')='manager' OR coalesce((t->>'capacity')::int,0)=1)) d;IF affected<>'[]'::jsonb AND NOT is_super THEN IF NOT private.base_org_scope_ok(auth.uid(),'org.assign_staff',affected) THEN RAISE EXCEPTION 'Bạn không có quyền phân công nhân sự trong phạm vi này.';END IF;IF manager_affected<>'[]'::jsonb AND NOT private.base_org_scope_ok(auth.uid(),'org.appoint_manager',manager_affected) THEN RAISE EXCEPTION 'Thay đổi vị trí quản lý cần quyền bổ nhiệm trong phạm vi.';END IF;IF EXISTS(SELECT 1 FROM jsonb_array_elements(_memberships) m JOIN jsonb_array_elements(c->'titles') t ON t->>'id'=m->>'title_id' WHERE m->>'user_id'=auth.uid()::text AND coalesce((m->>'active')::boolean,false) AND (coalesce(t->>'kind','')='manager' OR coalesce((t->>'capacity')::int,0)=1) AND NOT (c->'memberships') @> jsonb_build_array(m)) THEN RAISE EXCEPTION 'Không thể tự bổ nhiệm mình vào vị trí quản lý.';END IF;END IF;newc:=jsonb_set(c,'{memberships}',_memberships);PERFORM private.base_validate(newc);INSERT INTO base_org_state(id,revision,config) VALUES(true,v+1,newc) ON CONFLICT(id) DO UPDATE SET revision=v+1,config=newc,updated_at=now();INSERT INTO base_permission_events(actor_id,action,before_revision,after_revision,before_data,after_data,impact) VALUES(auth.uid(),left('membership_apply'||coalesce(' — '||nullif(trim(_reason),''),''),200),v,v+1,c,newc,'[]'::jsonb);RETURN v+1;END $$;
REVOKE ALL ON FUNCTION public.base_org_membership_apply(bigint,jsonb,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.base_org_membership_apply(bigint,jsonb,text) TO authenticated,service_role;
REVOKE ALL ON FUNCTION private.base_org_units_below(jsonb,text),private.base_org_scope_ok(uuid,text,jsonb) FROM PUBLIC,anon,authenticated;

-- Đọc cơ cấu: Super Admin thấy toàn bộ; người có quyền org.* thấy đơn vị/chức danh/phân công
-- nhưng KHÔNG thấy dữ liệu phân quyền nhạy cảm (quyền trực tiếp, bộ quyền, quyền mặc định).
CREATE OR REPLACE FUNCTION public.base_org_read() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE is_super boolean;c jsonb;rules jsonb;can_view boolean;can_hist boolean;BEGIN IF auth.uid() IS NULL OR NOT private.is_active(auth.uid()) THEN RAISE EXCEPTION 'Vui lòng đăng nhập lại.';END IF;is_super:=private.is_super_admin(auth.uid());c:=private.base_config();rules:=private.base_rules(auth.uid(),c);can_view:=is_super OR EXISTS(SELECT 1 FROM jsonb_array_elements(rules) r WHERE r->>'permission' IN ('org.view','org.assign_staff','org.appoint_manager','org.manage_structure') AND r->>'effect'='ALLOW');IF NOT can_view THEN RAISE EXCEPTION 'Chỉ Super Admin hoặc người được cấp quyền cơ cấu tổ chức.';END IF;can_hist:=is_super OR EXISTS(SELECT 1 FROM jsonb_array_elements(rules) r WHERE r->>'permission'='org.view_history' AND r->>'effect'='ALLOW');RETURN jsonb_build_object('revision',coalesce((SELECT revision FROM base_org_state WHERE id),0),'config',CASE WHEN is_super THEN c ELSE jsonb_set(jsonb_set(jsonb_set(jsonb_set(c,'{grants}','[]'::jsonb),'{bindings}','[]'::jsonb),'{bundles}','[]'::jsonb),'{defaults}','[]'::jsonb) END,'staff',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'name',full_name,'status',status) ORDER BY full_name),'[]') FROM profiles),'catalog',(SELECT coalesce(jsonb_agg(jsonb_build_object('key',key,'label',label,'module',module,'supported',private.base_supported(key)) ORDER BY module,key),'[]') FROM base_permission_catalog),'actor',jsonb_build_object('super',is_super,'assign_all',is_super OR EXISTS(SELECT 1 FROM jsonb_array_elements(rules) r WHERE r->>'permission'='org.assign_staff' AND r->>'effect'='ALLOW' AND r->>'unit_id' IS NULL),'assign_units',(SELECT coalesce(jsonb_agg(DISTINCT r->>'unit_id'),'[]'::jsonb) FROM jsonb_array_elements(rules) r WHERE r->>'permission'='org.assign_staff' AND r->>'effect'='ALLOW' AND r->>'unit_id' IS NOT NULL),'appoint_all',is_super OR EXISTS(SELECT 1 FROM jsonb_array_elements(rules) r WHERE r->>'permission'='org.appoint_manager' AND r->>'effect'='ALLOW' AND r->>'unit_id' IS NULL),'appoint_units',(SELECT coalesce(jsonb_agg(DISTINCT r->>'unit_id'),'[]'::jsonb) FROM jsonb_array_elements(rules) r WHERE r->>'permission'='org.appoint_manager' AND r->>'effect'='ALLOW' AND r->>'unit_id' IS NOT NULL),'view_history',can_hist),'events',CASE WHEN can_hist THEN (SELECT coalesce(jsonb_agg(x),'[]') FROM (SELECT id,actor_id,action,before_revision,after_revision,CASE WHEN is_super THEN impact ELSE '[]'::jsonb END impact,CASE WHEN is_super THEN before_data ELSE NULL END before_data,CASE WHEN is_super THEN after_data ELSE NULL END after_data,created_at FROM base_permission_events ORDER BY created_at DESC LIMIT 50)x) ELSE '[]'::jsonb END);END $$;

-- Danh mục quyền cơ cấu tổ chức (đồng bộ từ client vẫn cập nhật nhãn sau).
INSERT INTO base_permission_catalog(key,label,module,dependencies) VALUES ('org.view','Xem sơ đồ cơ cấu tổ chức','Cơ cấu tổ chức','{}'),('org.manage_structure','Tạo/sửa đơn vị và chức danh','Cơ cấu tổ chức','{}'),('org.assign_staff','Thêm, bỏ gán và điều chuyển nhân sự','Cơ cấu tổ chức','{}'),('org.appoint_manager','Bổ nhiệm/miễn nhiệm vị trí quản lý','Cơ cấu tổ chức','{}'),('org.view_history','Xem lịch sử phân công và bổ nhiệm','Cơ cấu tổ chức','{}'),('org.manage_permissions','Quản lý quy tắc phân quyền tổ chức','Cơ cấu tổ chức','{}') ON CONFLICT(key) DO NOTHING;